package com.exelynt.booking.service; import com.exelynt.booking.repository.UserRepository; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.userdetails.*; import org.springframework.stereotype.Service; import java.util.List;
@Service public class AppUserDetailsService implements UserDetailsService {private final UserRepository repo; public AppUserDetailsService(UserRepository r){repo=r;} public UserDetails loadUserByUsername(String n){var u=repo.findByUsername(n).orElseThrow(()->new UsernameNotFoundException("User not found"));return new org.springframework.security.core.userdetails.User(u.getUsername(),u.getPassword(),List.of(new SimpleGrantedAuthority("ROLE_"+u.getRole().name())));}}
